"""
    Function that converts a board (in FEN notation) in a list of lists of lines of the chess board
    Parameters :
        -board : the current board
    Returns :
        -arrayBoard : a list composed of lists(=lines) of the strings(=pieces)  of the boards
    """
def boardToArray(board: Any) -> object {
    board = board.replace("1", "-").replace("2", "--").replace("3", "---").replace(
        "4", "----"
    ).replace(
        "5", "-----"
    ).replace(
        "6", "------"
    ).replace(
        "7", "-------"
    ).replace(
        "8", "--------"
    );
    currentLine = [];
    listBoard = [];
    for (i, char) in enumerate(board) {
        if (char == ' ') {
            listBoard.append(currentLine);
            break;
        }
        if (((i + 1) % 9) == 0) {
            listBoard.append(currentLine);
            currentLine = [];
        } else {
            currentLine.append(char);
        }
    }
    return listBoard;
}

